mapper.select:
SELECT
FROM taolun a LEFT JOIN xuesheng xuesheng ON a.fabuzhe_table = 'xuesheng' AND a.fabuzhe_id = xuesheng.id LEFT JOIN laoshi laoshi ON a.fabuzhe_table = 'laoshi' AND a.fabuzhe_id = laoshi.id LEFT JOIN qiye qiye ON a.fabuzhe_table = 'qiye' AND a.fabuzhe_id = qiye.id LEFT JOIN users users ON a.fabuzhe_table = 'users' AND a.fabuzhe_id = users.id
and a.id in
#{item}
and a.fabuzhe_id = #{params.fabuzheId}
and a.fabuzhe_role = #{params.fabuzheRole}
and a.fabuzhe_table = #{params.fabuzheTable}
and ( a.fabuzhe_name like CONCAT('%',#{params.fabuzheName},'%') or xuesheng.xuesheng_name like CONCAT('%',#{params.fabuzheName},'%') or laoshi.laoshi_name like CONCAT('%',#{params.fabuzheName},'%') or qiye.qiye_name like CONCAT('%',#{params.fabuzheName},'%') or users.username like CONCAT('%',#{params.fabuzheName},'%') )
and a.taolun_title like CONCAT('%',#{params.taolunTitle},'%')
and a.taolun_content like CONCAT('%',#{params.taolunContent},'%')
order by a.${params.orderBy} desc
